let hexData = msg.payload;

// Zabezpieczenie przed uciętą ramką
if (!hexData || hexData.length < 200) return null;

let chunks = [];
for (let i = 0; i < hexData.length; i += 8) {
    chunks.push(hexData.substring(i, i + 8));
}

// Dekoder dla czujników analogowych (Wartość = 4 pierwsze znaki)
function decodeAnalog(chunk, divider = 1) {
    if (!chunk || chunk.length < 8) return null;
    let valueHex = chunk.substring(0, 4);
    let statusHex = chunk.substring(4, 8);

    let status = parseInt(statusHex, 16);
    // 136 lub 32767 to błąd czujnika / odpięty kabel
    if (status === 136 || status === 32767) return null;

    let value = parseInt(valueHex, 16);
    if (value > 32767) value -= 65536; // liczby ujemne (np. ujemne ciśnienie filtra)

    return Number((value / divider).toFixed(3));
}

// Dekoder dla liczników pełnych (np. starty)
function decodeCounter(chunk) {
    if (!chunk || chunk.length < 8) return null;
    return parseInt(chunk, 16);
}

// Dekoder dla godzin (sekundy na godziny)
function decodeHours(chunk) {
    if (!chunk || chunk.length < 8) return null;
    return Number((parseInt(chunk, 16) / 3600).toFixed(1));
}

// POPRAWIONY Dekoder wejść/wyjść cyfrowych (Mk5)
function decodeDigital(chunk) {
    if (!chunk || chunk.length < 8) return null;
    let valueHex = chunk.substring(0, 4);
    let statusHex = chunk.substring(4, 8);

    let status = parseInt(statusHex, 16);
    // 128 (0080 w hex) oznacza "Sygnał OK"
    if (status !== 128 && status !== 0) return null;

    let value = parseInt(valueHex, 16);
    return value > 0; // Zwraca true jeśli 1, false jeśli 0
}

let telemetry = {};

// ==========================================
// 1. CIŚNIENIA
// ==========================================
telemetry.cisnienie_wylotowe_bar = decodeAnalog(chunks[0], 1000);
telemetry.dp_filtra_powietrza_bar = decodeAnalog(chunks[1], 1000);
telemetry.cisnienie_wtrysku_oleju_bar = decodeAnalog(chunks[2], 1000);
telemetry.dp_separatora_oleju_bar = decodeAnalog(chunks[3], 1000);
telemetry.cisnienie_w_zbiorniku_bar = decodeAnalog(chunks[4], 1000);
telemetry.cisnienie_parowania_bar = decodeAnalog(chunks[10], 1000);
telemetry.cisnienie_skraplacza_bar = decodeAnalog(chunks[11], 100);

// ==========================================
// 2. TEMPERATURY
// ==========================================
telemetry.temp_wylot_ze_sprezarki_C = decodeAnalog(chunks[5], 10);
telemetry.temp_wylot_z_1_stopnia_C = decodeAnalog(chunks[6], 10);
telemetry.temp_wtrysk_oleju_C = decodeAnalog(chunks[7], 10);
telemetry.temp_wlot_pow_chlodz_C = decodeAnalog(chunks[8], 10);
telemetry.temp_otoczenia_C = decodeAnalog(chunks[9], 10);
telemetry.lat_osuszacza_1_C = decodeAnalog(chunks[12], 10);
telemetry.temp_wylot_cz_chlodn_sprezarki_1_C = decodeAnalog(chunks[13], 10);
telemetry.temp_czynnik_chlodniczy_1_C = decodeAnalog(chunks[14], 10);

// ==========================================
// 3. LICZNIKI CZASU PRACY
// ==========================================
telemetry.godziny_pracy = decodeHours(chunks[25]);
telemetry.czas_pracy_modulu = decodeHours(chunks[34]);

// ==========================================
// 4. STATYSTYKI I STARTY
// ==========================================
telemetry.startow_silnika = decodeCounter(chunks[26]);
telemetry.starty_osuszacza = decodeCounter(chunks[32]);
telemetry.starty_wentylatora = decodeCounter(chunks[33]);
telemetry.zatrzymania_awaryjne = decodeCounter(chunks[35]);
telemetry.zatrzymania_bezposrednie = decodeCounter(chunks[36]);

// ==========================================
// 5. FALOWNIK I PRZEPŁYW
// ==========================================
telemetry.falownik_abb_rpm = decodeAnalog(chunks[37], 1);
telemetry.przeplyw_proc = decodeCounter(chunks[38]);

// ==========================================
// 6. OBLICZANIE PROFILU VSD
// ==========================================
let vsd1 = decodeCounter(chunks[27]) || 0;
let vsd2 = decodeCounter(chunks[28]) || 0;
let vsd3 = decodeCounter(chunks[29]) || 0;
let vsd4 = decodeCounter(chunks[30]) || 0;
let vsd5 = decodeCounter(chunks[31]) || 0;
let vsd_total = vsd1 + vsd2 + vsd3 + vsd4 + vsd5;

if (vsd_total > 0) {
    telemetry.vsd_0_20_proc = Math.round((vsd1 / vsd_total) * 100);
    telemetry.vsd_20_40_proc = Math.round((vsd2 / vsd_total) * 100);
    telemetry.vsd_40_60_proc = Math.round((vsd3 / vsd_total) * 100);
    telemetry.vsd_60_80_proc = Math.round((vsd4 / vsd_total) * 100);
    telemetry.vsd_80_100_proc = Math.round((vsd5 / vsd_total) * 100);
}

// ==========================================
// 7. WEJŚCIA/WYJŚCIA CYFROWE (Korekta dla GA160)
// ==========================================

// Indeks 19 to adres 300307 - Emergency Stop (Logika odwrócona: 1=OK, 0=Błąd)
let safety_ok = decodeDigital(chunks[19]);

// Indeksy z grupy 3005xx (Stan rzeczywisty podzespołów)
// 300501 (Indeks 41) - Motor Running
// 300502 (Indeks 42) - Loading
// 300503 (Indeks 43) - Automatic Operation
let is_running = decodeDigital(chunks[41]);
let is_loaded = decodeDigital(chunks[42]);
let is_auto = decodeDigital(chunks[43]);
let is_warning = decodeDigital(chunks[18]); // 300305 - Ostrzeżenie

telemetry.silnik_pracuje = is_running;
telemetry.stan_dociazenia = is_loaded;
telemetry.praca_automatyczna = is_auto;

// ==========================================
// 8. LOGIKA STANU PRACY (Korekta warunków)
// ==========================================
let stan_maszyny = "Nieznany";

// Jeśli safety_ok jest FALSE (czyli 0), to mamy błąd
if (safety_ok === false) {
    stan_maszyny = "WYŁĄCZENIE AWARYJNE";
} else if (is_running && is_loaded) {
    stan_maszyny = "PRACA: DOCIĄŻONA";
} else if (is_running && !is_loaded) {
    stan_maszyny = "PRACA: ODCIĄŻONA";
} else if (!is_running && is_auto) {
    stan_maszyny = "CZUWANIE (AUTO)";
} else if (!is_running && !is_auto) {
    stan_maszyny = "ZATRZYMANA (RĘCZNY)";
}

if (is_warning) stan_maszyny += " / OSTRZEŻENIE";

telemetry.stan_maszyny = stan_maszyny;

// Czyszczenie payloadu z pustych wartości i błędów
Object.keys(telemetry).forEach(key => {
    if (telemetry[key] === null || Number.isNaN(telemetry[key])) delete telemetry[key];
});

msg.payload = telemetry;
return msg;

